#!/usr/bin/env python3
"""MSV1-INVINCIBLE — docs/msv1/invincible/LEDGER.md from slice_report.json (every sheet frame → where it is used)."""
import json, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
r = json.load(open(os.path.join(ROOT, 'docs/msv1/invincible/slice_report.json')))
ROWS = [('R1', ['r1_idle', 'r1_takeoff', 'r1_vstreak', 'r1_hstreak', 'r1_flight', 'r1_rings', 'r1_portrait']),
        ('R2', ['r2_walk', 'r2_lunge', 'r2_fpunch', 'r2_jump', 'r2_stand']),
        ('R3', ['r3_flurry', 'r3_upper', 'r3_burst']), ('R4', ['r4_sweep', 'r4_spin', 'r4_rise']),
        ('R5', ['r5_fly', 'r5_zip', 'r5_zstreak', 'r5_zpose', 'r5_zring']), ('R6', ['r6_hurt']), ('WIN', ['win']), ('LOSE', ['lose'])]
BRIEF = {'R1': 'idle 1, takeoff+shockwave 2, vertical streaks 2, horizontal streaks 2, flight 2, sonic rings 3, portrait 1 (= 13)',
         'R2': 'walk 4 · flying punch 2 · jump 2 · standing/idle 8 (= 16)', 'R3': 'flurry 5 · uppercut 3 + impact burst 2 (= 10)',
         'R4': 'sweep 3 · spin 3 · rising 3 (= 9)', 'R5': 'flying punch→burst 6 · zip: pose, silhouette, 2 streaks, 2 poses, 2 rings (= 14)',
         'R6': 'hurt → knockdown 5', 'WIN': '5', 'LOSE': '2'}
k = r['key']
L = ['# MSV1-INVINCIBLE — sprite ledger', '',
     f"Source `{r['source']}` {r['size'][0]}×{r['size'][1]}, background RGB{tuple(r['bg'])}. Generated by `tools/invincible/ledger.py`",
     'from `slice_report.json` (`tools/invincible/slice.py`). Body strips: `assets/invincible/<anim>.png` (feet-anchored; `ipunch` body-anchored),',
     'effects: `assets/invincible/fx/<name>.png`, portrait `assets/invincible/portrait.png`. Nearest-neighbour, drawn at ×3 in game.', '',
     '## Keying (no dark suit pixels lost)', '',
     f"* tolerance **0**: only pixels exactly RGB{tuple(r['bg'])} can be removed; flood from the panel borders removed {k['floodKeyedPx']:,} px.",
     f"* {k['enclosedPockets']} enclosed pockets of the exact background value ({k['enclosedPocketPx']} px — gaps between the legs / inside the white rings, each listed with its ring colours in slice_report.json) are keyed too.",
     f"* non-background pixels inside the used frames: **{k['nonBackgroundPxInFrames']:,}**, lost to keying: **{k['nonBackgroundPxLost']}** (asserted by the slicer).",
     f"* the suit's dark navy RGB(27,30,39) — 5 levels from the background — **{k['suitNavyPxInFrames']:,} px, all kept**.",
     f"* one logged stray: a 3-px RGB(32,30,38) sliver 3 px below the feet of the front-facing standing frame (sheet y 299–301, x 455) — invisible on the sheet, removed so the frame stands on the feet row.",
     '', '## Real frame counts per row (vs the brief\'s read)', '', '| row | real | brief read | frames |', '|---|---|---|---|']
total = 0
for row, keys in ROWS:
    n = sum(r['rows'][kk]['frames'] for kk in keys); total += n
    L.append(f"| {row} | **{n}** | {BRIEF[row]} | " + ', '.join(f"{kk} ×{r['rows'][kk]['frames']}" for kk in keys) + ' |')
L += [f'| total | **{total}** | | |', '',
      'Differences from the brief\'s read (all frames are used either way):',
      '* R1 — the takeoff is **1** frame with Mark inside the ground shockwave + **2** vertical-streak frames (each with its own ground ring), not 2 + 2.',
      '* R2 — the middle group is **3** frames: a leap pose + the **2** horizontal flying-punch frames (stacked vertically on the sheet). The "standing/idle 8" are a **turnaround** (side → 3/4 → front → 3/4 → side → back-3/4 → back → back-3/4), not an idle loop: they are the taunt / intro; the fighting idle is the fists-up stance of the walk frames played slowly.',
      '* R3 — **3** white impact bursts (small ring, big crescent, scatter), not 2.',
      '* R5 — **3** zip rings (small, big, scatter), not 2.',
      '* WIN — Mark pulls his mask off and swings it (5 frames); LOSE — unmasked and bruised (2).', '', '## Blood map + Edo Tensei', '', '* Blood map `data/bloodmaps/invincible.json` (tools/bloodmap/build.py): 80 indexed frames, 65 unique maps; harness/blood_coverage: 29 sheets drawn, 100% mapped.', '* Edo Tensei skin (tools/edoskin/gen.py, class **MASKED** — the suit mask covers his upper face, only the jaw is bare, the Batman case): `<strip>__edo.png` beside all 29 strips + `portrait__edo.png`; 1 crack, placed by a hash of the id. edo_skin.test 19/0.',
      '## Every frame → where it is used', '', '| frame | sheet box (y0, x0, y1, x1) | used in |', '|---|---|---|']
for row, keys in ROWS:
    for kk in keys:
        for i, b in enumerate(r['rows'][kk]['boxes']):
            L.append(f"| {kk}[{i}] | {tuple(b)} | {', '.join(r['coverage'][f'{kk}[{i}]'])} |")
L += ['', '## Excluded (and only these)', '']
ex = r['excluded']
L += [f"* header banner — {ex['header']}", f"* credit boxes, SWL+ logo, JUST ORUMA wordmark and the costume sample strip — {ex['credits+costume strip']} (samples = skin reference only, REUSE.md)",
      f"* the large standing figure on the right — {ex['bigFigure']}: logged, not used",
      f"* {sum(1 for l in ex['leftovers'] if l['kind'] == 'divider')} orange divider bars and the WIN / LOSE label letters ({sum(1 for l in ex['leftovers'] if l['kind'] == 'label')} pieces)",
      '', '## Strips', '', '| strip | frames | cell |', '|---|---|---|']
for kk, v in r['anims'].items(): L.append(f"| {kk} | {v['frames']} | {v['cell'][0]}×{v['cell'][1]} |")
for kk, v in r['fx'].items(): L.append(f"| fx/{kk} | {v['frames']} | {v['cell'][0]}×{v['cell'][1]} |")
L += ['', 'Compare sheet: `docs/msv1/invincible/compare.png` (every strip ×3 on a checkerboard).', '']
open(os.path.join(ROOT, 'docs/msv1/invincible/LEDGER.md'), 'w').write('\n'.join(L))
print('LEDGER rows', total)
